    const headX = getPhaseX(current.blueCount);
    const headY = getPhaseY(current.redCount);

    ctx.fillStyle = '#c084fc';
    ctx.shadowColor = '#c084fc';
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(headX, headY, 5.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
  }, [history, viewMode, isCollapsed]);

